PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://w3.org/ns/rev#>
SELECT ?sensor ?tsId ?sensorClass WHERE {
  ?zone rdfs:label "Perimeter_ZN_2".
  ?sensor brick:hasLocation ?zone .
  ?sensor brick:hasProperty [ a brick:HasInput ] .
  OPTIONAL { ?sensor ref:hasTimeseriesId ?tsId }
  ?sensor rdf:type ?sensorClass .
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?p ?class WHERE {
  ?zone rdfs:label "Perimeter_ZN_2".
  ?p brick:hasLocation ?zone .
  ?p rdf:type ?class .
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?x ?lbl WHERE {
  ?x rdfs:label ?lbl .
  FILTER(?lbl ? "Perimeter" || ?lbl ? "ZN_2")
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?x ?lbl WHERE {
  ?x rdfs:label ?lbl .
} LIMIT 50

